def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts = {}  # name -> (balance, frozen)
    history = []
    rejected = []
    arities = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    def parse_amount(token):
        if not token or not token.isascii() or not token.isdecimal():
            return None

        # Small chunks also support amounts beyond Python's int-string limit.
        value = 0
        for start in range(0, len(token), 18):
            chunk = token[start:start + 18]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        verb = parts[0]

        if not all(parts) or arities.get(verb) != len(parts):
            rejected.append(index)
            continue

        if verb == "undo":
            if not history:
                rejected.append(index)
                continue
            for name, previous in history.pop():
                if previous is None:
                    del accounts[name]
                else:
                    accounts[name] = previous
            continue

        if verb in ("open", "deposit", "withdraw", "transfer"):
            amount = parse_amount(parts[-1])
            if amount is None or (verb != "open" and amount == 0):
                rejected.append(index)
                continue

        name = parts[1]
        current = accounts.get(name)

        if verb == "open":
            if current is not None:
                rejected.append(index)
                continue
            changes = [(name, (amount, False))]

        elif current is None:
            rejected.append(index)
            continue

        elif verb == "deposit":
            balance, frozen = current
            changes = [(name, (balance + amount, frozen))]

        elif verb == "withdraw":
            balance, frozen = current
            if frozen or balance < amount:
                rejected.append(index)
                continue
            changes = [(name, (balance - amount, frozen))]

        elif verb == "transfer":
            destination = parts[2]
            target = accounts.get(destination)
            balance, frozen = current

            if (
                name == destination
                or target is None
                or frozen
                or balance < amount
            ):
                rejected.append(index)
                continue

            changes = [
                (name, (balance - amount, frozen)),
                (destination, (target[0] + amount, target[1])),
            ]

        else:
            balance, frozen = current
            new_frozen = verb == "freeze"
            if frozen == new_frozen:
                rejected.append(index)
                continue
            changes = [(name, (balance, new_frozen))]

        history.append([
            (changed_name, accounts.get(changed_name))
            for changed_name, _ in changes
        ])
        for changed_name, new_state in changes:
            accounts[changed_name] = new_state

    return {
        name: state[0] for name, state in accounts.items()
    }, rejected
